// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public { c = new Reentrance(); }

    // fuzz parameters: depositor key and deposit amount
    function testFuzz_property(uint256 depositorKey, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        depositorKey = bound(depositorKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // keep amount in a reasonable range and non-zero so addToBalance actually sends value
        amount = bound(amount, 1, 1 ether);

        address depositor = vm.addr(uint256(depositorKey));

        // give depositor enough ETH to send
        vm.deal(depositor, amount + 1 ether);

        // depositor deposits 'amount' into c via addToBalance()
        vm.prank(depositor);
        c.addToBalance{value: amount}();

        // record contract balance before withdraw
        uint256 beforeContractBalance = address(c).balance;

        // call withdrawBalance as depositor, catch revert (both reference and mutant should not revert)
        bool ok;
        vm.prank(depositor);
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference property: withdrawBalance succeeds (does not revert) for any depositor who previously deposited,
        // and after withdrawal c.getBalance(depositor) == 0 and contract balance decreased by amount.
        // (The mutant that sends value 0 will leave contract balance unchanged and thus violate the property.)

        // The single assertion reads c's public surface (getBalance and address(c).balance via before/after).
        uint256 afterContractBalance = address(c).balance;
        // getBalance should be zero after successful withdrawal
        assertTrue(ok && c.getBalance(depositor) == 0 && beforeContractBalance - afterContractBalance == amount);
    }
}
